# ═══════════════════════════════════════════════════════════════
# polaris-cli — Forge 渲染引擎命令行(二进制名 polaris-forge)
#
# 给 agent(claude CLI)/脚本/Docker 直接调用:preflight / 截图 / deck→pptx /
# spec→pptx / deck→video / tts / pptx 校验,与桌面端同一份引擎源码。
#
# ★ 坑(47d1e0c 实证):CLI 绝不能做主包 [[bin]] —— tauri bundler 会按
#   [[bin]] 列表连坐 copy,打桌面包必炸。独立 crate 是唯一安全姿势。
#   构建:cargo build -p polaris-cli --release   (产物 target/release/polaris-forge)
# ═══════════════════════════════════════════════════════════════
[package]
name = "polaris-cli"
version = "2.8.0"
edition = "2021"
description = "polaris-forge — Polaris Forge 渲染引擎 CLI"
publish = false

[[bin]]
name = "polaris-forge"
path = "src/main.rs"

# Docker 服务端入口。曾是主包 [[bin]],47d1e0c 因 tauri bundler 连坐被迫删除;
# 落户本 crate = bundler 不可见 + server feature 经依赖恒开,desktop 打包零影响。
[[bin]]
name = "polaris-server"
path = "src/bin/polaris-server.rs"

# collab-net(iroh 打洞直连)透传:polaris-server 镜像加 `--features collab-net` 即让
# 服务端起 iroh host_listen 暴露 NodeId,桌面/手机可 P2P 连入。polaris-forge 不带,零额外编译。
[features]
collab-net = ["polaris-app/collab-net"]

[dependencies]
# 复用主 lib 的全部引擎(forge 五件套 + convert)。server feature 是 Docker 侧
# 验证过的无-tauri 已知良好组合;CLI 不起 HTTP,只是借这条特性线拿引擎。
polaris-app = { path = "../..", default-features = false, features = ["server"] }
serde_json = "1"
# polaris-server bin 跑 async serve() 用;与主 lib 的 tokio 同版本统一,零额外编译。
tokio = { version = "1", features = ["rt-multi-thread"] }

/// dir 是否(忽略大小写/尾斜杠)出现在分号分隔的 PATH 串里。
pub(crate) fn path_contains_dir(path_str: &str, dir: &str) -> bool {
    let norm = |s: &str| s.trim().trim_end_matches(['\\', '/']).to_lowercase();
    let target = norm(dir);
    if target.is_empty() {
        return false;
    }
    path_str.split(if cfg!(windows) { ';' } else { ':' }).any(|p| norm(p) == target)
}

/// 把 dir 前插进**当前进程 PATH** (若尚不在其中)。仅改本进程、不碰注册表; 返回是否真加了。
/// 这是「装完 / 启动后不重启即可 spawn claude」的底座 —— 子进程继承本进程 env。
pub(crate) fn prepend_process_path(dir: &str) -> bool {
    let dir = dir.trim();
    if dir.is_empty() {
        return false;
    }
    let proc_path = std::env::var("PATH").unwrap_or_default();
    if path_contains_dir(&proc_path, dir) {
        return false;
    }
    let sep = if cfg!(windows) { ';' } else { ':' };
    let new = if proc_path.is_empty() {
        dir.to_string()
        .filter(|l| !l.is_empty())
        .map(PathBuf::from)
        .filter(|p| p.exists())
        .collect()
}

/// 首个非空行 (优先 stdout, 个别工具把版本写到 stderr); 进程非零退出 → None。
pub(super) fn first_line(out: &std::process::Output) -> Option<String> {
    if !out.status.success() {
        return None;
    }
    let pick = |bytes: &[u8]| -> Option<String> {
        String::from_utf8_lossy(bytes)
            .lines()
            .map(|l| l.trim())
            .find(|l| !l.is_empty())
            .map(|s| s.to_string())
    };
    pick(&out.stdout).or_else(|| pick(&out.stderr))
}

